class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        skip = False
        for i, row in enumerate(grid):
            # Traverse row left-to-right on even rows, right-to-left on odd rows
            cells = row if i % 2 == 0 else row[::-1]
            for val in cells:
                if not skip:
                    result.append(val)
                skip = not skip
        return result
